from collections import defaultdict

class Solution:
    def numberOfPaths(self, grid: List[List[int]], k: int) -> int:
        mod = 10**9 + 7
        dp = defaultdict(int)
        dp[0, 0] = 1

        for i in range(len(grid)):
            for j in range(len(grid[0])):
                prev_dp = dp.copy()

                # Calculate new values based on previous states
                for x, y in [(i-1, j), (i, j-1)]:
                    if 0 <= x < len(grid) and 0 <= y < len(grid[0]):
                        dp[x, y] = (prev_dp[x, y] + prev_dp[x, (y+k)%k]) % mod

        return dp[len(grid)-1, len(grid[0])-1]

from itertools import combinations

class Solution:
    def sumCounts(self, nums: List[int]) -> int:
        mod = 10**9 + 7

        # Calculate the number of unique elements in each subarray
        n = len(nums)
        dp = [[0 for _ in range(n)] for _ in range(n)]
        for length in range(1, n+1):
            for start in range(n-length+1):
                end = start + length - 1
                if length == 1:
                    dp[start][end] = 1
                else:
                    dp[start][end] = dp[start+1][end] + dp[start][end-1] - dp[start+1][end-1]

        # Calculate the sum of squares of distinct counts
        total_sum = 0
        for start in range(n):
            for end in range(start, n):
                distinct_count = dp[start][end]
                total_sum += distinct_count * distinct_count

        return total_sum % mod

