class Solution:
    def countDistinct(self, nums: List[int], k: int, p: int) -> int:
        n = len(nums)
        count = 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                if sum([num % p == 0 for num in nums[j - i:j]]) <= k:
                    count += 1
        return count

