class Solution:
    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])
        count = 0

        # Iterate over each cell in the grid
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    # Check all other cells in the same row
                    for k in range(cols):
                        if k != j and grid[i][k] == 1:
                            # Check all other cells in the same column
                            for l in range(rows):
                                if l != i and grid[l][j] == 1 and grid[l][k] == 1:
                                    count += 1

        return count // 6  # Each triangle is counted 6 times

class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        perimeter = 0

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    # Each land cell contributes at least 4 to the perimeter
                    perimeter += 4

                    # Subtract 1 for each adjacent land cell (up)
                    if i > 0 and grid[i-1][j] == 1:
                        perimeter -= 1

                    # Subtract 1 for each adjacent land cell (left)
                    if j > 0 and grid[i][j-1] == 1:
                        perimeter -= 1

        return perimeter

