class Solution:
    def maxSumSubmatrix(self, matrix: List[List[int]], k: int) -> int:
        m, n = len(matrix), len(matrix[0])
        dp = [[0 for _ in range(n)] for _ in range(m)]
        res = float('-inf')

        for i in range(m):
            for j in range(n):
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

                left, right = j - 1, j + 1
                while left >= 0 and right < n:
                    temp_sum = dp[i][right] - (dp[i][left] if left >= 0 else 0)
                    res = max(res, temp_sum)
                    if temp_sum <= k:
                        right += 1
                    else:
                        left -= 1

        return res

