class TrieNode:
    def __init__(self):
        self.children = {}
        self.count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, num):
        node = self.root
        for i in range(15, -1, -1):
            bit = (num >> i) & 1
            if bit not in node.children:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1

    def query(self, num, bound):
        node = self.root
        res = 0
        for i in range(15, -1, -1):
            bit = (num >> i) & 1
            target_bit = (bound >> i) & 1

            if target_bit == 1:
                if bit in node.children:
                    res += node.children[bit].count
                if 1 - bit in node.children:
                    node = node.children[1 - bit]
            else:
                if bit in node.children:
                    node = node.children[bit]
                else:
                    break

        return res

class Solution:
    def countPairs(self, nums: List[int], low: int, high: int) -> int:
        trie = Trie()
        ans = 0
        for num in nums:
            ans += trie.query(num, high + 1) - trie.query(num, low)
            trie.insert(num)
        return ans

