class Solution:
    def longestPalindrome(self, s: str) -> int:
        n = len(s)
        if n < 2:
            return n

        # Find the middle character
        mid = s[n // 2]

        # Check if the middle character is a palindrome
        if mid == mid[::-1]:
            return n - 1

        # Check if the middle character is a non-palindrome and the left side is a palindrome
        if mid != mid[::-1] and s[:n // 2] == s[n // 2:]:
            return n - 2

        # Check if the middle character is a non-palindrome and the right side is a palindrome
        if mid != mid[::-1] and s[n // 2:] == s[:n // 2][::-1]:
            return n - 2

        # If none of the above conditions are met, it's a palindrome
        return n

