class Solution:
    def binaryTreePaths(self, root: Optional[TreeNode]) -> List[str]:
        if not root:
            return []

        def dfs(node, path, result):
            if not node.left and not node.right:
                result.append('->'.join(path))
                return
            if node.left:
                dfs(node.left, path + [str(node.left.val)], result)
            if node.right:
                dfs(node.right, path + [str(node.right.val)], result)

        result = []
        dfs(root, [str(root.val)], result)
        return result

class Solution:
    def magicalString(self, n: int) -> int:
        if n <= 0:
            return 0

        s = [1, 2, 2]
        i, count = 2, 1

        while len(s) < n:
            next_value = 3 - s[i]
            for _ in range(s[i]):
                s.append(next_value)
            i += 1
            count += next_value

        return min(count, n)

class Solution:
    def countPalindromicSubsequence(self, s: str) -> int:
        n = len(s)
        dp = [[0] * (n + 1) for _ in range(n + 1)]

        # Fill the dp table
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if s[i - 1] == s[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        # Count the number of unique palindromic subsequences
        return dp[n][n]

