class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        if k == 0:
            return sum(1 for num in nums if num == 0)

        count = 0
        left = 0
        current_and = 0

        for right in range(len(nums)):
            current_and &= nums[right]

            while current_and < k and left <= right:
                current_and |= nums[left]
                left += 1

            if current_and == k:
                count += right - left + 1

        return count

class Solution:
    def minCost(self, costs: List[List[int]]) -> int:
        if not costs:
            return 0

        # Initialize the dp array with the first house's costs
        dp = [costs[0][0], costs[0][1], costs[0][2]]

        # Iterate over the remaining houses
        for i in range(1, len(costs)):
            # Update the dp array with the minimum cost to paint the current house
            dp[0] = costs[i][0] + min(dp[1], dp[2])
            dp[1] = costs[i][1] + min(dp[0], dp[2])
            dp[2] = costs[i][2] + min(dp[0], dp[1])

        # Return the minimum cost to paint all houses
        return min(dp)

class Solution:
    def bestHand(self, ranks: List[int], suits: List[str]) -> str:
        # Check if all cards have the same suit
        if len(set(suits)) != 1:
            return "High Card"

        # Check if there are exactly three cards of the same rank
        for rank in set(ranks):
            count = ranks.count(rank)
            if count == 3:
                return "Three of a Kind"

        # Check if there is exactly one card of each rank
        for rank in set(ranks):
            if ranks.count(rank) > 1:
                return "Pair"

        # If none of the above conditions are met, return "Flush"
        return "Flush"

class Solution:
    def minimumMoves(self, grid: List[List[int]]) -> int:
        n = len(grid)
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up
        visited = set()
        queue = [(0, 0, 0, 1, False)]  # x1, y1, x2, y2, is_horizontal

        while queue:
            x1, y1, x2, y2, is_horizontal = queue.pop(0)

            if (x1, y1, x2, y2, is_horizontal) in visited:
                continue

            visited.add((x1, y1, x2, y2, is_horizontal))

            if (x1 == n-1 and y1 == n-2) and (x2 == n-1 and y2 == n-1):
                return is_horizontal * 2 + 1

            if is_horizontal:
                # Try moving right
                if y1 < n-1 and grid[x1][y1+1] == 0 and grid[x2][y2+1] == 0:
                    queue.append((x1, y1+1, x2, y2+1, True))

                # Try moving down
                if x1 < n-1 and grid[x1+1][y1] == 0 and grid[x1+1][y2] == 0:
                    queue.append((x1+1, y1, x1+1, y2, True))

                # Try rotating clockwise
                if x1 < n-1 and y1 < n-2 and grid[x1+1][y1+1] == 0 and grid[x1+1][y1+2] == 0:
                    queue.append((x1, y1, x1+1, y1+1, False))
            else:
                # Try moving down
                if x1 < n-1 and grid[x1+1][y1] == 0 and grid[x1+1][y2] == 0:
                    queue.append((x1+1, y1, x1+1, y2, False))

                # Try moving right
                if y1 < n-1 and grid[x1][y1+1] == 0 and grid[x2][y2+1] == 0:
                    queue.append((x1, y1+1, x2, y2+1, False))

                # Try rotating counterclockwise
                if x1 < n-1 and y1 < n-2 and grid[x1+1][y1+1] == 0 and grid[x1+1][y1+2] == 0:
                    queue.append((x1, y1, x1+1, y1+1, True))

        return -1

class Solution:
    def countDigits(self, num: int) -> int:
        # Convert the number to a string to iterate over each digit
        num_str = str(num)
        # Initialize a counter for digits that divide the number
        count = 0

        # Iterate over each character in the string representation of the number
        for digit in num_str:
            # Check if the digit is divisible by the number
            if int(digit) % num == 0:
                count += 1

        return count

from heapq import heappop, heappush

class Solution:
    def totalCost(self, costs: List[int], k: int, candidates: int) -> int:
        n = len(costs)
        if 2 * candidates >= n:
            return sum(sorted(costs)[:k])

        left, right = candidates, max(n - candidates - 1, 0)
        min_heap_left = costs[:left]
        min_heap_right = costs[right:] if right != n else []

        heappify(min_heap_left)
        heappify(min_heap_right)

        total_cost = 0
        for _ in range(k):
            if not min_heap_left:
                total_cost += heappop(min_heap_right)
            elif not min_heap_right:
                total_cost += heappop(min_heap_left)
            elif min_heap_left[0] <= min_heap_right[0]:
                total_cost += heappop(min_heap_left)
                if left <= right:
                    heappush(min_heap_left, costs[left])
                    left += 1
            else:
                total_cost += heappop(min_heap_right)
                if left <= right:
                    heappush(min_heap_right, costs[right])
                    right -= 1

        return total_cost

class Solution:
    def getLastMoment(self, n: int, left: List[int], right: List[int]) -> int:
        # Initialize the maximum time to the current position
        max_time = 0

        # Iterate through the left array to find the last position where an ant is moving to the right
        for i in range(len(left)):
            if left[i] >= n - 1:
                max_time = max(max_time, i)

        # Iterate through the right array to find the last position where an ant is moving to the left
        for i in range(len(right)):
            if right[i] < 0:
                max_time = max(max_time, n - 1 - i)

        return max_time

from functools import lru_cache

class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        @lru_cache(None)
        def dp(i, tight, current_sum):
            if i == len(num2):
                return 1 if min_sum <= current_sum <= max_sum else 0

            upper_bound = int(num2[i]) if tight else 9
            total_count = 0

            for d in range(upper_bound + 1):
                new_tight = tight and d == upper_bound
                total_count += dp(i + 1, new_tight, current_sum + d)

            return total_count % MOD

        # Adjust num1 to have leading zeros if necessary
        num1 = '0' * (len(num2) - len(num1)) + num1

        return (dp(0, True, 0) - dp(len(num1), True, 0) + MOD) % MOD

class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        ans = n // k + 1 if n % k else 0

        for i in range(1, n):
            if word[i - 1] == word[i]:
                ans += 1
            else:
                break

        return ans

class Solution:
    def getMaximumGenerated(self, n: int) -> int:
        if n == 0:
            return 0
        elif n == 1:
            return 1

        nums = [0, 1]
        for i in range(2, n + 1):
            if 2 <= 2 * i <= n:
                nums.append(nums[i - 1])
            else:
                nums.append(nums[i - 1] + nums[i - 2])

        return max(nums)

