class Solution:
    def isCompleteTree(self, root: Optional[TreeNode]) -> bool:
        queue = deque([root])
        while queue:
            node = queue.popleft()
            if not node:
                break
            queue.append(node.left)
            queue.append(node.right)
        return not any(queue)

class Solution:
    def dividePlayers(self, skill: List[int]) -> int:
        skill.sort()
        i = 0
        j = len(skill)-1
        total_sum = 0

        while i < j:
            if skill[i] + skill[j] != total_sum:
                return -1

            total_sum += skill[i] * skill[j]
            i += 1
            j -= 1

        return total_sum

class Solution:
    def grayCode(self, n: int) -> List[int]:
        if n == 0:
            return [0]
        gray = []
        gray.append(0)
        gray.append(1)
        for i in range(2, n + 1):
            gray.append(gray[i - 1] | (1 << (i - 1)))
        return gray

