class Solution:
    def medianOfUniquenessArray(self, nums: List[int]) -> int:
        count = Counter(nums)
        unique_counts = sorted(count.values())
        n = len(unique_counts)

        if n % 2 == 1:
            return unique_counts[n // 2]
        else:
            return (unique_counts[n // 2 - 1] + unique_counts[n // 2]) / 2

from typing import List

class Solution:
    def maxPower(self, stations: List[int], r: int, k: int) -> int:
        n = len(stations)
        prefix_sum = [0] * (n + 1)

        # Calculate the initial power for each city
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + stations[i]

        current_power = [0] * n
        for i in range(n):
            left = max(0, i - r)
            right = min(n, i + r + 1)
            current_power[i] = prefix_sum[right] - prefix_sum[left]

        # Binary search for the maximum possible minimum power
        low, high = 0, 10**11
        while low < high:
            mid = (low + high + 1) // 2
            extra_stations = 0
            need = 0

            for i in range(n):
                if current_power[i] < mid:
                    need = mid - current_power[i]
                    extra_stations += need
                    if extra_stations > k:
                        break

                if i + 2 * r + 1 < n:
                    current_power[i + 2 * r + 1] += need

            if extra_stations <= k:
                low = mid
            else:
                high = mid - 1

        return low

