import heapq

class Solution:
    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        min_prices = []
        max_profits = []
        heapq.heapify(min_prices)
        heapq.heapify(max_profits)

        for i in range(len(prices)):
            while min_prices and min_prices[0][0] >= prices[i]:
                heapq.heappop(min_prices)
            heapq.heappush(min_prices, (prices[i], i))

            while max_profits and max_profits[0][0] <= prices[i]:
                heapq.heappop(max_profits)
            heapq.heappush(max_profits, (-profits[i], i))

        result = float('-inf')
        while len(min_prices) > 1:
            first_min = heapq.heappop(min_prices)
            second_min = heapq.heappop(min_prices)
            third_min = heapq.heappop(min_prices)
            if second_min[0] < first_min[0] < third_min[0]:
                result = max(result, first_min[0] + second_min[0] + third_min[0])

        return result if result != float('-inf') else -1

class Solution:
    def findPairs(self, nums: List[int], k: int) -> int:
        count = 0
        nums.sort()
        for i in range(len(nums)):
            left = i + 1
            right = len(nums) - 1
            while left < right:
                if nums[i] + nums[right] == k:
                    count += 1
                    left += 1
                    right -= 1
                elif nums[i] + nums[right] < k:
                    left += 1
                else:
                    right -= 1
        return count

