class Solution:
    def countQuadruplets(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for j in range(1, n - 1):
            less_i = greater_k = 0
            for i in range(j):
                if nums[i] < nums[j]:
                    less_i += 1
            for k in range(j + 1, n):
                if nums[k] > nums[j]:
                    greater_k += 1
            ans += less_i * greater_k
        return ans

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        ops = 0
        prev = nums[0]
        for num in nums[1:]:
            if num > prev:
                prev = num
            else:
                ops += prev + 1 - num
                prev += prev + 1 - num
        return ops

class Solution:
    def calculate(self, s: str) -> int:
        stack = []
        num = 0
        sign = '+'

        for i, char in enumerate(s):
            if char.isdigit():
                num = num * 10 + int(char)

            if (char == '+' or char == '-' or char == ')' or i == len(s) - 1):
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)

                if char == ')':
                    temp = 0
                    while stack and stack[-1] != '(':
                        temp += stack.pop()

                    if stack and stack[-1] == '(':
                        stack.pop()

                    stack.append(temp)

                sign = char
                num = 0

        return sum(stack)

from collections import Counter

class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        counter = Counter(words)
        odd_count = sum(1 for count in counter.values() if count % 2 != 0)

        # If there are an odd number of characters, we can form at most half of them as palindromes
        if odd_count > len(words) // 2:
            return 0

        # We can form as many palindromes as possible from the even counts
        palindromes = len(words) - odd_count

        # We can also form palindromes from the odd counts by pairing them up
        for count in counter.values():
            if count % 2 == 0:
                palindromes += count // 2
            else:
                palindromes += (count - 1) // 2

        return palindromes

class Solution:
    def goodIndices(self, nums: List[int], k: int) -> List[int]:
        return sorted([i for i in range(k, len(nums) - k) if nums[i - 1] < nums[i] and nums[i + 1] < nums[i]])

class Solution:
    def findIntersectionValues(self, nums1: List[int], nums2: List[int]) -> List[int]:
        return [len(set(nums1)) - len(set(nums2)), len(set(nums2)) - len(set(nums1))]

